const REQUIRED_LABEL = "ia";

return items.filter((item) => {
  const body = item.json?.body;
  const labels = body?.conversation?.labels || [];
  const messageType = body?.message_type;

  const hasIaLabel = labels.includes(REQUIRED_LABEL);
  const isIncoming = messageType === "incoming";

  return hasIaLabel && isIncoming;
});

